window.DEX_DATA["sources:backport-9bbfb54a5521c44e"]={"json":{"skins":[{"filename":"ornithologist.png"}],"names":[{"name":"伯德先生"},{"name":"威尔弗雷德·沃布勒"},{"name":"杰弗里·特威普"},{"name":"爱鸟人伯特伦"},{"name":"伯德教授"}],"chat":[{"lines":[{"text":"烈雀飞过天空的景象，真是百看不厌！"},{"text":"真希望自己记得带鸟食。"}]},{"lines":[{"text":"红冠大比鸟的筑巢习惯，和褐色咕咕出奇地相似。"},{"text":"观察鸟宝可梦特别有趣，你也该试试。"}]},{"lines":[{"text":"有时为了看见一只猫头夜鹰，我得在森林里躲上好几个星期。"},{"text":"睡在地上不太舒服，可总得有人做这份工作嘛！"}]},{"lines":[{"text":"我的工作很重要，训练鸟宝可梦需要的知识，都来自我们的研究。"},{"text":"可怜的鸟类学家，也是宝可梦研究中默默无闻的英雄啊。"}]},{"lines":[{"text":"请问你有面包吗？我用来吸引姆克儿的鸟食吃完了。"},{"text":"我的望远镜性能可好了，十英里外的小姆克儿都看得见！"}]}]}};
